arguments.new_str:
using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF Core 9 changed the discriminator property from "Discriminator" to "$type".
        // Revert to the EF8 name so existing documents (and raw SQL queries) keep working.
        configurationBuilder.Conventions.Remove(
            typeof(Microsoft.EntityFrameworkCore.Cosmos.Metadata.Conventions.CosmosDiscriminatorConvention));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // Keep the EF8 discriminator property name for the 500K existing documents.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Product");

            // EF Core 9 no longer prepends the type name to the id.
            // Existing ids are "Product|123"; restore that format.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonPropertyName("id")
                  .HasValueGenerator<ProductIdValueGenerator>();
        });
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

/// <summary>
/// Reproduces the EF8 "EntityType|KeyValue" id format for new inserts.
/// </summary>
class ProductIdValueGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<int>
{
    public override bool GeneratesTemporaryValues => false;
    public override int Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => throw new NotSupportedException("Id must be supplied explicitly.");
}

