using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.Metadata.Conventions;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // BREAKING CHANGE 1 — Discriminator property renamed.
        // EF Core 9 defaults to "$type" instead of "Discriminator".
        // Remove the new convention so our explicit HasDiscriminator call is respected,
        // keeping the property name that the 500K existing documents already contain.
        configurationBuilder.Conventions.Remove(typeof(CosmosDiscriminatorConvention));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // Preserve the EF8 discriminator property name for existing documents
            // and for raw SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Product");

            // BREAKING CHANGE 2 — JSON id format changed.
            // EF8 stored id as "Product|123"; EF9 stores just "123".
            // Define the __id shadow property explicitly with the EF8 format
            // so reads of existing documents still match.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGenerator<Ef8IdValueGenerator>();
        });
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

/// <summary>
/// Reproduces the EF8 Cosmos id format: "EntityTypeName|KeyValue".
/// </summary>
class Ef8IdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var pk = entry.Property("Id").CurrentValue;
        return $"{entityType}|{pk}";
    }
}

